changeSet.sql:
CREATE FUNCTION rastroos_tmp_easter(p_year int) RETURNS date AS $$
DECLARE a int; b int; c int; d int; e int; f int; g int; h int;
        i int; k int; l int; m int; mo int; da int;
BEGIN
    a := p_year % 19;  b := p_year / 100;  c := p_year % 100;
    d := b / 4;        e := b % 4;         f := (b + 8) / 25;
    g := (b - f + 1) / 3;
    h := (19 * a + b - d - g + 15) % 30;
    i := c / 4;        k := c % 4;
    l := (32 + 2 * e + 2 * i - h - k) % 7;
    m := (a + 11 * h + 22 * l) / 451;
    mo := (h + l - 7 * m + 114) / 31;
    da := ((h + l - 7 * m + 114) % 31) + 1;
    RETURN make_date(p_year, mo, da);
END; $$ LANGUAGE plpgsql IMMUTABLE;

CREATE FUNCTION rastroos_tmp_is_holiday(p_date date) RETURNS boolean AS $$
DECLARE y int; ea date;
BEGIN
    y := extract(year from p_date)::int;
    ea := rastroos_tmp_easter(y);
    RETURN p_date IN (
        make_date(y, 1, 1), make_date(y, 4, 21), make_date(y, 5, 1),
        make_date(y, 9, 7), make_date(y, 10, 12), make_date(y, 11, 2),
        make_date(y, 11, 15), make_date(y, 12, 25),
        ea - 48, ea - 47, ea - 2, ea + 60
    ) OR (y >= 2024 AND p_date = make_date(y, 11, 20));
END; $$ LANGUAGE plpgsql IMMUTABLE;

CREATE FUNCTION rastroos_tmp_nth_business_day(p_month_start date, p_nth int)
RETURNS date AS $$
DECLARE d date; last_bd date; cnt int := 0; target int;
BEGIN
    target := greatest(1, p_nth);
    FOR d IN
        SELECT generate_series(p_month_start,
                               (p_month_start + interval '1 month - 1 day')::date,
                               interval '1 day')::date
    LOOP
        IF extract(isodow from d) < 6 AND NOT rastroos_tmp_is_holiday(d) THEN
            cnt := cnt + 1;
            last_bd := d;
            IF cnt = target THEN RETURN d; END IF;
        END IF;
    END LOOP;
    RETURN coalesce(last_bd, (p_month_start + interval '1 month - 1 day')::date);
END; $$ LANGUAGE plpgsql IMMUTABLE;

-- Só do mês corrente em diante: o que já foi recebido fica como
-- foi registrado, exatamente como no update() da receita fixa.
UPDATE incomes i
   SET income_date = rastroos_tmp_nth_business_day(
           date_trunc('month', i.income_date)::date, s.pay_business_day)
  FROM income_sources s
 WHERE i.source_id = s.id
   AND i.income_date >= date_trunc('month', CURRENT_DATE)::date;

DROP FUNCTION rastroos_tmp_nth_business_day(date, int);
DROP FUNCTION rastroos_tmp_is_holiday(date);
DROP FUNCTION rastroos_tmp_easter(int);
